import java.util.*; public class Week01Problem02 { public static void main(String[] z){Scanner s=new Scanner(System.in);String a=s.nextLine(),b=s.nextLine();if(a.length()!=b.length()){System.out.println("Strings must have equal length");return;}int m=0,k=-1;for(int i=0;i<a.length();i++)if(a.charAt(i)==b.charAt(i))m++;else if(k<0)k=i;System.out.println("Matched characters: "+m);System.out.printf("Accuracy: %.2f%%%n",a.isEmpty()?100.0:m*100.0/a.length());System.out.println("First mismatch index: "+k);}}